def place(shop, items):
    return shop.orders.handle_create({"customer_id": "c1", "items": items}).body["order_id"]


def test_packing_slip(shop):
    oid = place(shop, [{"sku": "PEN", "quantity": 3}, {"sku": "BOOK", "quantity": 1}])
    res = shop.fulfilment.handle_packing_slip(oid)
    assert res.status == 200
    assert res.body == {"order_id": oid, "customer_name": "Ada", "lines": [
        {"sku": "PEN", "name": "Pen", "quantity": 3},
        {"sku": "BOOK", "name": "Book", "quantity": 1}]}


def test_packing_slip_unknown_order(shop):
    res = shop.fulfilment.handle_packing_slip("nope")
    assert (res.status, res.body) == (404, {"error": "order not found"})


def test_packing_slip_cancelled_order(shop):
    oid = place(shop, [{"sku": "PEN", "quantity": 1}])
    shop.orders.handle_cancel(oid)
    res = shop.fulfilment.handle_packing_slip(oid)
    assert res.status == 409
    assert "error" in res.body


def test_low_stock_sorted_and_strict(shop):
    shop.catalog.handle_add_product({"sku": "ALPHA", "name": "Alpha", "unit_price_cents": 1, "on_hand": 5})
    res = shop.fulfilment.handle_low_stock(100)
    assert res.status == 200
    assert res.body["products"] == [
        {"sku": "ALPHA", "name": "Alpha", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
        {"sku": "BOOK", "name": "Book", "on_hand": 50}]
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    assert shop.fulfilment.handle_low_stock(0).body == {"products": []}


