    import dataclasses
    # No endpoint deactivates products, so replace one directly in the catalogue.
    catalog = shop.fulfilment._service._catalog
    catalog.add(dataclasses.replace(catalog.get("LAMP"), active=False))
    assert shop.fulfilment.handle_low_stock(10).body == {"products": []}


